-- Game scripts (JR, Oct 15, 2026; PROJECT_SPEC §2.14): one canonical story per completed game (quarter scores,
-- scoring order with scorers and clock, lead changes, key moments, adjustments), generated by
-- engines/game_script_engine.py so every writer tells the same story. Untracked detail is invented; the script
-- never contradicts the box score.
--
-- Run ./db/backup_db.sh first. Idempotent. Apply with:
--   docker exec -i madden-db psql -U postgres -d madden -v ON_ERROR_STOP=1 < db/migrations/2026_11_18_game_scripts.sql

BEGIN;

CREATE TABLE IF NOT EXISTS game_scripts (
    game_id INTEGER PRIMARY KEY REFERENCES games(id) ON DELETE CASCADE,
    season INTEGER NOT NULL,
    week INTEGER NOT NULL,
    version INTEGER NOT NULL,
    facts_hash TEXT NOT NULL,
    script JSONB NOT NULL,
    generated_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS idx_game_scripts_season_week ON game_scripts(season, week);

COMMIT;
